import{_ as s,o as n,c as e,a5 as p}from"./chunks/framework.DJo0M80U.js";const g=JSON.parse('{"title":"78. 崩溃分析和核心转储","description":"The Little Book of C 中文版 — 78. 崩溃分析和核心转储","frontmatter":{"title":"78. 崩溃分析和核心转储","date":"2026-07-04","lang":"zh-CN","categories":["C 教程"],"tags":["C","Little Book of C","08-调试测试与 profiling","中文"],"description":"The Little Book of C 中文版 — 78. 崩溃分析和核心转储","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","translator":"机器辅助翻译（Google Translate）","section":78,"sidebarWeight":78,"alternateZh":"/posts/c教程/zh-CN/08-调试测试与 profiling/078-Crash Analysis and Core Dumps","alternateEn":"/posts/c教程/en-US/08-Debugging Testing Profiling/078-Crash Analysis and Core Dumps"},"headers":[],"relativePath":"posts/c教程/zh-CN/08-调试测试与 profiling/078-Crash Analysis and Core Dumps.md","filePath":"posts/c教程/zh-CN/08-调试测试与 profiling/078-Crash Analysis and Core Dumps.md","lastUpdated":1790163617000}'),i={name:"posts/c教程/zh-CN/08-调试测试与 profiling/078-Crash Analysis and Core Dumps.md"};function t(l,a,c,o,d,h){return n(),e("div",null,[...a[0]||(a[0]=[p(`<p>[English version](/posts/c教程/en-US/08-Debugging Testing Profiling/078-Crash Analysis and Core Dumps)</p><p>即使进行了仔细的编码和测试，程序也会崩溃。在 C 语言中，崩溃是系统表达“你触及了不该触及的东西”的方式。好消息是，您可以使用核心转储（故障时程序内存的快照）科学地分析崩溃。</p><p>学习如何阅读它们是每个系统程序员的一项基本技能。</p><h4 id="步骤-1-什么是核心转储" tabindex="-1">步骤 1.什么是核心转储？ <a class="header-anchor" href="#步骤-1-什么是核心转储" aria-label="Permalink to &quot;步骤 1.什么是核心转储？&quot;">​</a></h4><p>核心转储是一个捕获程序崩溃时的状态（堆栈、寄存器、内存）的文件。您可以稍后使用 gdb 之类的调试器检查它，看看出了什么问题。</p><p>生成核心转储的常见崩溃信号：</p><ul><li>SIGSEGV – 无效的内存访问（分段错误）</li><li>SIGABRT – 断言失败</li><li>SIGFPE – 算术错误（如被零除）</li><li>SIGILL – 非法指令</li></ul><h4 id="步骤-2-启用核心转储" tabindex="-1">步骤 2. 启用核心转储 <a class="header-anchor" href="#步骤-2-启用核心转储" aria-label="Permalink to &quot;步骤 2. 启用核心转储&quot;">​</a></h4><p>默认情况下，现代系统会限制或禁用它们。使用以下方法启用它们：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ulimit -c unlimited</span></span></code></pre></div><p>查看：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ulimit -a | grep core</span></span></code></pre></div><p>现在，当你的程序崩溃时，一个名为<code>core</code>或者<code>core. </code>将会出现。</p><h4 id="步骤-3-一个崩溃的例子" tabindex="-1">步骤 3. 一个崩溃的例子 <a class="header-anchor" href="#步骤-3-一个崩溃的例子" aria-label="Permalink to &quot;步骤 3. 一个崩溃的例子&quot;">​</a></h4><p>让我们做一个简单的崩溃：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int *p = NULL;</span></span>
<span class="line"><span>    *p = 42;</span><span>  // crash: dereferencing null pointer</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>编译并运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc crash.c -g -o crash</span></span>
<span class="line"><span>./crash</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Segmentation fault (core dumped)</span></span></code></pre></div><p>一个<code>core</code>文件现已在您的目录中创建。</p><h4 id="步骤-4-在-gdb-中打开核心转储" tabindex="-1">步骤 4. 在 gdb 中打开核心转储 <a class="header-anchor" href="#步骤-4-在-gdb-中打开核心转储" aria-label="Permalink to &quot;步骤 4. 在 gdb 中打开核心转储&quot;">​</a></h4><p>使用 gdb 检查发生了什么：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gdb ./crash core</span></span></code></pre></div><p>你会看到：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Core was generated by \`./crash&#39;.</span></span>
<span class="line"><span>Program terminated with signal SIGSEGV, Segmentation fault.</span></span>
<span class="line"><span>#0  0x0000000000401136 in main () at crash.c:5</span></span>
<span class="line"><span>5       *p = 42;</span></span></code></pre></div><p>这会告诉您程序崩溃的确切行。</p><h4 id="步骤-5-检查变量和堆栈" tabindex="-1">步骤 5. 检查变量和堆栈 <a class="header-anchor" href="#步骤-5-检查变量和堆栈" aria-label="Permalink to &quot;步骤 5. 检查变量和堆栈&quot;">​</a></h4><p>在 gdb 中：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(gdb) bt</span></span></code></pre></div><p>显示回溯，即崩溃时的调用堆栈。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#0  main () at crash.c:5</span></span></code></pre></div><p>您可以检查变量：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(gdb) info locals</span></span>
<span class="line"><span>(gdb) print p</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$1 = (int *) 0x0</span></span></code></pre></div><h4 id="步骤-6-更复杂的示例" tabindex="-1">步骤 6. 更复杂的示例 <a class="header-anchor" href="#步骤-6-更复杂的示例" aria-label="Permalink to &quot;步骤 6. 更复杂的示例&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>void f3(int *p) {</span></span>
<span class="line"><span>    *p = 7;</span><span>  // likely crash here</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>void f2(int *p) {</span></span>
<span class="line"><span>    f3(p);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>void f1(void) {</span></span>
<span class="line"><span>    int *x = NULL;</span></span>
<span class="line"><span>    f2(x);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    f1();</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>运行它，使其崩溃，然后：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gdb ./crash core</span></span></code></pre></div><p>内部gdb：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(gdb) bt</span></span>
<span class="line"><span>#0  f3 (p=0x0) at crash.c:4</span></span>
<span class="line"><span>#1  f2 (p=0x0) at crash.c:8</span></span>
<span class="line"><span>#2  f1 () at crash.c:12</span></span>
<span class="line"><span>#3  main () at crash.c:16</span></span></code></pre></div><p>您可以看到导致空取消引用的整个调用链。</p><h4 id="步骤-7-调试优化构建" tabindex="-1">步骤 7. 调试优化构建 <a class="header-anchor" href="#步骤-7-调试优化构建" aria-label="Permalink to &quot;步骤 7. 调试优化构建&quot;">​</a></h4><p>当你编译时<code>-O2</code>或者<code>-O3</code>，编译器可能会内联或重新排序代码，从而使调试变得更加困难。对于调试，请始终使用：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -g -O0 crash.c -o crash</span></span></code></pre></div><p>这<code>-g</code>flag 保存符号信息（文件名、行号）。没有它，除了地址之外，gdb 无法告诉您更多信息。</p><h4 id="步骤-8-控制核心转储位置" tabindex="-1">步骤 8. 控制核心转储位置 <a class="header-anchor" href="#步骤-8-控制核心转储位置" aria-label="Permalink to &quot;步骤 8. 控制核心转储位置&quot;">​</a></h4><p>更改转储的存储位置：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo sysctl -w kernel.core_pattern=/tmp/core.%e.%p</span></span></code></pre></div><p>这个例子将它们保存在<code>/tmp</code>包含程序名称和进程 ID：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/tmp/core.crash.1234</span></span></code></pre></div><h4 id="步骤-9-崩溃分析工作流程" tabindex="-1">步骤 9. 崩溃分析工作流程 <a class="header-anchor" href="#步骤-9-崩溃分析工作流程" aria-label="Permalink to &quot;步骤 9. 崩溃分析工作流程&quot;">​</a></h4><p>启用转储：<code>ulimit -c unlimited</code></p><p>运行程序直到崩溃</p><p>找到核心文件</p><p>用gdb分析：</p><p>-<code>bt</code>用于堆栈跟踪 -<code>info locals</code>对于本地变量 -<code>frame </code>检查每个堆栈帧 -<code>list</code>查看附近的代码</p><p>这可以让您全面了解失败之前发生的情况。</p><h4 id="步骤-10-小代码-断言失败分析" tabindex="-1">步骤 10. 小代码：断言失败分析 <a class="header-anchor" href="#步骤-10-小代码-断言失败分析" aria-label="Permalink to &quot;步骤 10. 小代码：断言失败分析&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;assert.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int x = 5;</span></span>
<span class="line"><span>    assert(x == 10);  // fails</span></span>
<span class="line"><span>    printf(&quot;Done\\n&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>编译并运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -g assert_fail.c -o assert_fail</span></span>
<span class="line"><span>ulimit -c unlimited</span></span>
<span class="line"><span>./assert_fail</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assert_fail: assert_fail.c:5: main: Assertion \`x == 10&#39; failed.</span></span>
<span class="line"><span>Aborted (core dumped)</span></span></code></pre></div><p>现在检查：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gdb ./assert_fail core</span></span>
<span class="line"><span>(gdb) bt</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#0  0x00007f0a9a4b9187 in raise () from /lib64/libc.so.6</span></span>
<span class="line"><span>#1  0x00007f0a9a4c53e8 in abort () from /lib64/libc.so.6</span></span>
<span class="line"><span>#2  0x00007f0a9a4b0246 in __assert_fail_base () from /lib64/libc.so.6</span></span>
<span class="line"><span>#3  0x00007f0a9a4b02f2 in __assert_fail () from /lib64/libc.so.6</span></span>
<span class="line"><span>#4  0x0000000000401136 in main () at assert_fail.c:5</span></span></code></pre></div><p>您可以准确跟踪断言如何导致中止信号。</p><h4 id="为什么它很重要" tabindex="-1">为什么它很重要 <a class="header-anchor" href="#为什么它很重要" aria-label="Permalink to &quot;为什么它很重要&quot;">​</a></h4><p>崩溃分析将混乱变得清晰。您可以：</p><ul><li>查看哪一行导致了崩溃。</li><li>检查此时的所有变量。</li><li>快速重现并修复错误。</li></ul><p>每个认真的 C 程序员都必须掌握这一点，这是系统工程师调试从用户工具到内核的所有内容的方法。</p><h4 id="自己尝试一下" tabindex="-1">自己尝试一下 <a class="header-anchor" href="#自己尝试一下" aria-label="Permalink to &quot;自己尝试一下&quot;">​</a></h4><ol><li>编写一个取消引用空指针的小程序。</li><li>启用核心转储（<code>ulimit -c unlimited</code>).</li><li>崩溃，然后在 gdb 中分析转储。</li><li>再添加一层函数并检查调用链。</li><li>尝试<code>SIGFPE</code>（除以零）并查看核心转储有何不同。</li></ol><p>接下来，您将为 C 项目、习惯和原则构建一个代码审查清单，以帮助防止这些崩溃发生。</p>`,77)])])}const b=s(i,[["render",t]]);export{g as __pageData,b as default};
